// Original CSS perspective illustration: no external asset, library, canvas or WebGL.
export function renderDepth(root,{counts,reserve},view){
 const doc=root.ownerDocument;if(!doc.querySelector('link[data-depth-style]')){const css=doc.createElement('link');css.rel='stylesheet';css.href=new URL('./depth-view.css',import.meta.url).href;css.dataset.depthStyle='';doc.head.append(css);}
 root.innerHTML=`<p>Otra perspectiva de la colección activa. El registro anterior queda fuera de esta vista.</p><div class="depth-controls"><button type="button" class="action secondary" data-depth-front aria-pressed="${!view.angle}">Vista frontal · 2D</button><button type="button" class="action secondary" data-depth-angle aria-pressed="${view.angle}">Vista inclinada</button></div><div class="depth-scene" data-angle="${view.angle}"><div class="depth-table" aria-hidden="true">${[...counts,reserve].map((n,i)=>`<div class="depth-tray"><b>${['A','B','Reserva'][i]}</b><div class="depth-tokens">${Array.from({length:n},()=>'<i class="depth-token"></i>').join('')}${!n?'<span>0</span>':''}</div></div>`).join('')}</div></div><p class="depth-description">Parte A: ${counts[0]}. Parte B: ${counts[1]}. Reserva: ${reserve}. Solo A y B forman la suma actual.</p><p class="quiet">Mueve las fichas con los botones de las bandejas de arriba. La inclinación, el espacio y la forma del dibujo no cambian la cantidad.</p>`;
 const set=angle=>{view.angle=angle;root.querySelector('.depth-scene').dataset.angle=String(angle);root.querySelector('[data-depth-front]').setAttribute('aria-pressed',String(!angle));root.querySelector('[data-depth-angle]').setAttribute('aria-pressed',String(angle));};
 root.querySelector('[data-depth-front]').onclick=()=>set(false);root.querySelector('[data-depth-angle]').onclick=()=>set(true);
}
